-- EduNova v0.24.1 LOT 23 FINAL MAXIMAL — syllabus, outcomes, progress and immutable resource revision history.
CREATE TABLE teaching_syllabi(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,offering_id varchar(64) NOT NULL REFERENCES teaching_offerings(id) ON DELETE RESTRICT,version integer NOT NULL CHECK(version>0),title varchar(240) NOT NULL,overview varchar(8000) NOT NULL DEFAULT '',learning_outcomes varchar(12000) NOT NULL DEFAULT '',state varchar(24) NOT NULL CHECK(state IN ('draft','approved','superseded')),row_version integer NOT NULL CHECK(row_version>0),created_by varchar(64) NOT NULL,approved_by varchar(64),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(offering_id,version));
CREATE TABLE teaching_syllabus_topics(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,syllabus_id varchar(64) NOT NULL REFERENCES teaching_syllabi(id) ON DELETE RESTRICT,position integer NOT NULL CHECK(position>0),title varchar(240) NOT NULL,description varchar(8000) NOT NULL DEFAULT '',learning_objectives varchar(12000) NOT NULL DEFAULT '',concept_refs varchar(12000) NOT NULL DEFAULT '',planned_minutes integer NOT NULL DEFAULT 0 CHECK(planned_minutes>=0),state varchar(24) NOT NULL CHECK(state IN ('planned','in_progress','taught','skipped')),row_version integer NOT NULL CHECK(row_version>0),updated_at timestamptz NOT NULL,UNIQUE(syllabus_id,position));
CREATE TABLE teaching_resource_revisions(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,resource_id varchar(64) NOT NULL REFERENCES teaching_resources(id) ON DELETE RESTRICT,revision_no integer NOT NULL CHECK(revision_no>0),title varchar(240) NOT NULL,uri varchar(1500) NOT NULL,source_revision varchar(128),change_note varchar(2000) NOT NULL DEFAULT '',created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,UNIQUE(resource_id,revision_no));
CREATE INDEX ix_teaching_syllabus_offering_state ON teaching_syllabi(institution_id,offering_id,state,version);
CREATE INDEX ix_teaching_topic_progress ON teaching_syllabus_topics(institution_id,syllabus_id,state,position);
CREATE INDEX ix_teaching_resource_revision_history ON teaching_resource_revisions(institution_id,resource_id,revision_no);
